// Package apigen generates allapi_gen.go: a program that references every
// exported function and every exported method of an exported type of the
// library packages, so that a build of it compiles all of the library API.
package apigen

import (
	"bytes"
	"errors"
	"fmt"
	"go/ast"
	"go/build"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"
)

const modulePath = "github.com/USA-RedDragon/dmrgo/v2"

// Out is the path of the generated file, relative to the module directory.
const Out = "internal/allocgate/allapi/allapi_gen.go"

// Generate returns the content of allapi_gen.go for the module in dir. It
// reads the files that a build without cgo uses, as TinyGo builds.
func Generate(dir string) ([]byte, error) {
	ctx := build.Default
	ctx.CgoEnabled = false
	ctx.GOOS, ctx.GOARCH = "linux", "amd64"
	skipDirs := []string{"cmd", "examples", "internal/allocgate", "internal/fecref", "internal/outputdigest", "internal/text/texttest", "internal/unpacked", "vocoder/codec2/internal/aot"}
	var refs, imports []string
	err := filepath.WalkDir(dir, func(p string, d os.DirEntry, err error) error {
		if err != nil || !d.IsDir() {
			return err
		}
		rel, _ := filepath.Rel(dir, p)
		rel = filepath.ToSlash(rel)
		if d.Name() == "testdata" || slices.ContainsFunc(skipDirs, func(s string) bool { return rel == s || strings.HasPrefix(rel, s+"/") }) {
			return filepath.SkipDir
		}
		if _, err := os.Stat(filepath.Join(p, "go.mod")); err == nil && rel != "." {
			return filepath.SkipDir
		}
		bp, err := ctx.ImportDir(p, 0)
		if err != nil {
			if errors.As(err, new(*build.NoGoError)) {
				return nil
			}
			return err
		}
		if bp.Name == "main" {
			return nil
		}
		importPath := modulePath
		if rel != "." {
			importPath = path.Join(modulePath, rel)
		}
		alias := strings.ReplaceAll(strings.TrimPrefix(strings.TrimPrefix(importPath, modulePath), "/"), "/", "_")
		if alias == "" {
			alias = "dmrgo"
		}
		pkgRefs, err := exports(p, bp.GoFiles, alias)
		if err != nil {
			return err
		}
		if len(pkgRefs) > 0 {
			imports = append(imports, fmt.Sprintf("%s %q", alias, importPath))
			refs = append(refs, pkgRefs...)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	var b bytes.Buffer
	b.WriteString("// Code generated by go run ./internal/allocgate/apigen/gen; DO NOT EDIT.\n\n")
	b.WriteString("// Command allapi references every exported function and method of the\n")
	b.WriteString("// library, so that tinygo build -print-allocs compiles and checks all of\n")
	b.WriteString("// the library API.\n")
	b.WriteString("package main\n\nimport (\n")
	for _, i := range imports {
		b.WriteString("\t" + i + "\n")
	}
	b.WriteString(")\n\nvar api = [...]any{\n")
	for _, r := range refs {
		b.WriteString("\t" + r + ",\n")
	}
	b.WriteString("}\n\nfunc main() {\n\tfor i := range api {\n\t\tuse(api[i])\n\t}\n}\n\n")
	b.WriteString("//go:noinline\nfunc use(f any) {\n\t_ = f\n}\n")
	return format.Source(b.Bytes())
}

func exports(dir string, files []string, alias string) ([]string, error) {
	fset := token.NewFileSet()
	types := map[string]bool{}
	var parsed []*ast.File
	for _, f := range files {
		af, err := parser.ParseFile(fset, filepath.Join(dir, f), nil, parser.SkipObjectResolution)
		if err != nil {
			return nil, err
		}
		parsed = append(parsed, af)
		for _, d := range af.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok || gd.Tok != token.TYPE {
				continue
			}
			for _, s := range gd.Specs {
				ts, ok := s.(*ast.TypeSpec)
				if ok && ts.Name.IsExported() && ts.TypeParams == nil && !ts.Assign.IsValid() {
					types[ts.Name.Name] = true
				}
			}
		}
	}
	var refs []string
	for _, af := range parsed {
		for _, d := range af.Decls {
			fd, ok := d.(*ast.FuncDecl)
			if !ok || !fd.Name.IsExported() || fd.Type.TypeParams != nil {
				continue
			}
			if fd.Recv == nil {
				refs = append(refs, alias+"."+fd.Name.Name)
				continue
			}
			recv := fd.Recv.List[0].Type
			ptr := false
			if s, ok := recv.(*ast.StarExpr); ok {
				recv, ptr = s.X, true
			}
			id, ok := recv.(*ast.Ident)
			if !ok || !types[id.Name] {
				continue
			}
			if ptr {
				refs = append(refs, "(*"+alias+"."+id.Name+")."+fd.Name.Name)
			} else {
				refs = append(refs, alias+"."+id.Name+"."+fd.Name.Name)
			}
		}
	}
	slices.Sort(refs)
	return refs, nil
}
